1	package v1
2	
3	import (
4		"context"
5		stderrors "errors"
6		"fmt"
7		"log/slog"
8		"time"
9	
10		"github.com/pkg/errors"
11		"google.golang.org/protobuf/types/known/timestamppb"
12	
13		v1pb "github.com/usememos/memos/proto/gen/api/v1"
14		storepb "github.com/usememos/memos/proto/gen/store"
15		"github.com/usememos/memos/store"
16	)
17	
18	var (
19		errMemoCreatorNotFound     = stderrors.New("memo creator not found")
20		errReactionCreatorNotFound = stderrors.New("reaction creator not found")
21	)
22	
23	func (s *APIV1Service) convertMemoFromStore(ctx context.Context, memo *store.Memo, reactions []*store.Reaction, attachments []*store.Attachment, relations []*v1pb.MemoRelation) (*v1pb.Memo, error) {
24		creatorMap, err := s.listUsersByID(ctx, []int32{memo.CreatorID})
25		if err != nil {
26			return nil, errors.Wrap(err, "failed to list memo creators")
27		}
28		return s.convertMemoFromStoreWithCreators(ctx, memo, reactions, attachments, relations, creatorMap)
29	}
30	
31	func (s *APIV1Service) convertMemoFromStoreWithCreators(ctx context.Context, memo *store.Memo, reactions []*store.Reaction, attachments []*store.Attachment, relations []*v1pb.MemoRelation, creatorMap map[int32]*store.User) (*v1pb.Memo, error) {
32		name := fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID)
33		creator := creatorMap[memo.CreatorID]
34		if creator == nil {
35			return nil, errMemoCreatorNotFound
36		}
37		memoMessage := &v1pb.Memo{
38			Name:       name,
39			State:      convertStateFromStore(memo.RowStatus),
40			Creator:    BuildUserName(creator.Username),
41			CreateTime: timestamppb.New(time.Unix(memo.CreatedTs, 0)),
42			UpdateTime: timestamppb.New(time.Unix(memo.UpdatedTs, 0)),
43			Content:    memo.Content,
44			Visibility: convertVisibilityFromStore(memo.Visibility),
45			Pinned:     memo.Pinned,
46		}
47		if memo.Payload != nil {
48			memoMessage.Tags = memo.Payload.Tags
49			memoMessage.Property = convertMemoPropertyFromStore(memo.Payload.Property)
50			memoMessage.Location = convertLocationFromStore(memo.Payload.Location)
51		}
52	
53		if memo.ParentUID != nil {
54			parentName := fmt.Sprintf("%s%s", MemoNamePrefix, *memo.ParentUID)
55			memoMessage.Parent = &parentName
56		}
57	
58		reactionMessages, err := s.convertReactionsFromStoreWithCreators(ctx, reactions, creatorMap)
59		if err != nil {
60			return nil, errors.Wrap(err, "failed to convert reactions")
61		}
62		memoMessage.Reactions = reactionMessages
63	
64		if relations != nil {
65			memoMessage.Relations = relations
66		} else {
67			memoMessage.Relations = []*v1pb.MemoRelation{}
68		}
69	
70		memoMessage.Attachments = []*v1pb.Attachment{}
71		for _, attachment := range attachments {
72			attachmentResponse := convertAttachmentFromStore(attachment)
73			memoMessage.Attachments = append(memoMessage.Attachments, attachmentResponse)
74		}
75	
76		snippet, err := s.getMemoContentSnippet(memo.Content)
77		if err != nil {
78			return nil, errors.Wrap(err, "failed to get memo content snippet")
79		}
80		memoMessage.Snippet = snippet
81	
82		return memoMessage, nil
83	}
84	
85	func (s *APIV1Service) listUsersByIDWithExisting(ctx context.Context, userIDs []int32, existing map[int32]*store.User) (map[int32]*store.User, error) {
86		usersByID := make(map[int32]*store.User, len(existing)+len(userIDs))
87		for userID, user := range existing {
88			if user != nil {
89				usersByID[userID] = user
90			}
91		}
92	
93		missingUserIDs := make([]int32, 0, len(userIDs))
94		seenMissingUserIDs := make(map[int32]struct{}, len(userIDs))
95		for _, userID := range userIDs {
96			if _, ok := usersByID[userID]; ok {
97				continue
98			}
99			if _, ok := seenMissingUserIDs[userID]; ok {
100				continue
101			}
102			seenMissingUserIDs[userID] = struct{}{}
103			missingUserIDs = append(missingUserIDs, userID)
104		}
105	
106		if len(missingUserIDs) == 0 {
107			return usersByID, nil
108		}
109	
110		missingUsersByID, err := s.listUsersByID(ctx, missingUserIDs)
111		if err != nil {
112			return nil, err
113		}
114		for userID, user := range missingUsersByID {
115			if user != nil {
116				usersByID[userID] = user
117			}
118		}
119		return usersByID, nil
120	}
121	
122	func (s *APIV1Service) convertReactionsFromStoreWithCreators(ctx context.Context, reactions []*store.Reaction, creatorMap map[int32]*store.User) ([]*v1pb.Reaction, error) {
123		if len(reactions) == 0 {
124			return []*v1pb.Reaction{}, nil
125		}
126	
127		creatorIDs := make([]int32, 0, len(reactions))
128		for _, reaction := range reactions {
129			creatorIDs = append(creatorIDs, reaction.CreatorID)
130		}
131		creatorsByID, err := s.listUsersByIDWithExisting(ctx, creatorIDs, creatorMap)
132		if err != nil {
133			return nil, err
134		}
135	
136		reactionMessages := make([]*v1pb.Reaction, 0, len(reactions))
137		for _, reaction := range reactions {
138			reactionMessage, err := convertReactionFromStoreWithCreators(reaction, creatorsByID)
139			if err != nil {
140				if stderrors.Is(err, errReactionCreatorNotFound) {
141					slog.Warn("Skipping reaction with missing creator",
142						slog.Int64("reaction_id", int64(reaction.ID)),
143						slog.Int64("creator_id", int64(reaction.CreatorID)),
144						slog.String("content_id", reaction.ContentID),
145					)
146					continue
147				}
148				return nil, err
149			}
150			reactionMessages = append(reactionMessages, reactionMessage)
151		}
152		return reactionMessages, nil
153	}
154	
155	func convertReactionFromStoreWithCreators(reaction *store.Reaction, creatorsByID map[int32]*store.User) (*v1pb.Reaction, error) {
156		creator := creatorsByID[reaction.CreatorID]
157		if creator == nil {
158			return nil, errReactionCreatorNotFound
159		}
160	
161		reactionUID := fmt.Sprintf("%d", reaction.ID)
162		return &v1pb.Reaction{
163			Name:         fmt.Sprintf("%s/%s%s", reaction.ContentID, ReactionNamePrefix, reactionUID),
164			Creator:      BuildUserName(creator.Username),
165			ContentId:    reaction.ContentID,
166			ReactionType: reaction.ReactionType,
167			CreateTime:   timestamppb.New(time.Unix(reaction.CreatedTs, 0)),
168		}, nil
169	}
170	
171	// batchConvertMemoRelations batch-loads relations for a list of memos and returns
172	// a map from memo ID to its converted relations. This avoids N+1 queries when listing memos.
173	func (s *APIV1Service) batchConvertMemoRelations(ctx context.Context, memos []*store.Memo, includeSnippets bool) (map[int32][]*v1pb.MemoRelation, error) {
174		if len(memos) == 0 {
175			return map[int32][]*v1pb.MemoRelation{}, nil
176		}
177	
178		currentUser, err := s.fetchCurrentUser(ctx)
179		if err != nil {
180			return nil, errors.Wrap(err, "failed to get user")
181		}
182		var memoFilter string
183		if currentUser == nil {
184			memoFilter = `visibility == "PUBLIC"`
185		} else {
186			memoFilter = fmt.Sprintf(`creator_id == %d || visibility in ["PUBLIC", "PROTECTED"]`, currentUser.ID)
187		}
188	
189		memoIDs := make([]int32, len(memos))
190		memoIDSet := make(map[int32]bool, len(memos))
191		for i, m := range memos {
192			memoIDs[i] = m.ID
193			memoIDSet[m.ID] = true
194		}
195	
196		outgoingRelations, err := s.Store.ListMemoRelations(ctx, &store.FindMemoRelation{
197			SourceMemoIDList: memoIDs,
198			MemoFilter:       &memoFilter,
199		})
200		if err != nil {
201			return nil, errors.Wrap(err, "failed to batch list outgoing memo relations")
202		}
203		incomingRelations, err := s.Store.ListMemoRelations(ctx, &store.FindMemoRelation{
204			RelatedMemoIDList: memoIDs,
205			MemoFilter:        &memoFilter,
206		})
207		if err != nil {
208			return nil, errors.Wrap(err, "failed to batch list incoming memo relations")
209		}
210		allRelations := mergeMemoRelations(outgoingRelations, incomingRelations)
211	
212		// Collect all memo IDs referenced in relations that we need to resolve.
213		neededIDs := make(map[int32]bool)
214		for _, r := range allRelations {
215			neededIDs[r.MemoID] = true
216			neededIDs[r.RelatedMemoID] = true
217		}
218	
219		// Build ID→UID map from the memos we already have.
220		memoIDToUID := make(map[int32]string, len(memos))
221		memoIDToSnippet := make(map[int32]string, len(memos))
222		for _, m := range memos {
223			memoIDToUID[m.ID] = m.UID
224			if includeSnippets {
225				snippet, err := s.getMemoContentSnippet(m.Content)
226				if err != nil {
227					return nil, errors.Wrap(err, "failed to get memo content snippet")
228				}
229				memoIDToSnippet[m.ID] = snippet
230			}
231			delete(neededIDs, m.ID)
232		}
233	
234		// Batch fetch any additional memos referenced by relations that we don't already have.
235		if len(neededIDs) > 0 {
236			extraIDs := make([]int32, 0, len(neededIDs))
237			for id := range neededIDs {
238				extraIDs = append(extraIDs, id)
239			}
240			extraFind := &store.FindMemo{IDList: extraIDs, ExcludeContent: !includeSnippets}
241			extraMemos, err := s.Store.ListMemos(ctx, extraFind)
242			if err != nil {
243				return nil, errors.Wrap(err, "failed to batch fetch related memos")
244			}
245			for _, m := range extraMemos {
246				memoIDToUID[m.ID] = m.UID
247				if includeSnippets {
248					snippet, err := s.getMemoContentSnippet(m.Content)
249					if err != nil {
250						return nil, errors.Wrap(err, "failed to get related memo content snippet")
251					}
252					memoIDToSnippet[m.ID] = snippet
253				}
254			}
255		}
256	
257		// Build the result map: memo ID → its relations (both directions).
258		result := make(map[int32][]*v1pb.MemoRelation, len(memos))
259		for _, r := range allRelations {
260			memoUID, ok1 := memoIDToUID[r.MemoID]
261			relatedUID, ok2 := memoIDToUID[r.RelatedMemoID]
262			if !ok1 || !ok2 {
263				continue
264			}
265	
266			relation := &v1pb.MemoRelation{
267				Memo: &v1pb.MemoRelation_Memo{
268					Name:    fmt.Sprintf("%s%s", MemoNamePrefix, memoUID),
269					Snippet: memoIDToSnippet[r.MemoID],
270				},
271				RelatedMemo: &v1pb.MemoRelation_Memo{
272					Name:    fmt.Sprintf("%s%s", MemoNamePrefix, relatedUID),
273					Snippet: memoIDToSnippet[r.RelatedMemoID],
274				},
275				Type: convertMemoRelationTypeFromStore(r.Type),
276			}
277	
278			// Add to the memo that owns this relation (both directions).
279			if memoIDSet[r.MemoID] {
280				result[r.MemoID] = append(result[r.MemoID], relation)
281			}
282			if memoIDSet[r.RelatedMemoID] {
283				result[r.RelatedMemoID] = append(result[r.RelatedMemoID], relation)
284			}
285		}
286	
287		return result, nil
288	}
289	
290	// loadMemoRelations loads relations for a single memo and converts them to API format.
291	func (s *APIV1Service) loadMemoRelations(ctx context.Context, memo *store.Memo) ([]*v1pb.MemoRelation, error) {
292		relationMap, err := s.batchConvertMemoRelations(ctx, []*store.Memo{memo}, true)
293		if err != nil {
294			return nil, err
295		}
296		return relationMap[memo.ID], nil
297	}
298	
299	func mergeMemoRelations(groups ...[]*store.MemoRelation) []*store.MemoRelation {
300		seen := make(map[string]struct{})
301		merged := make([]*store.MemoRelation, 0)
302		for _, relations := range groups {
303			for _, relation := range relations {
304				key := fmt.Sprintf("%d:%d:%s", relation.MemoID, relation.RelatedMemoID, relation.Type)
305				if _, ok := seen[key]; ok {
306					continue
307				}
308				seen[key] = struct{}{}
309				merged = append(merged, relation)
310			}
311		}
312		return merged
313	}
314	
315	func convertMemoPropertyFromStore(property *storepb.MemoPayload_Property) *v1pb.Memo_Property {
316		if property == nil {
317			return nil
318		}
319		return &v1pb.Memo_Property{
320			HasLink:            property.HasLink,
321			HasTaskList:        property.HasTaskList,
322			HasCode:            property.HasCode,
323			HasIncompleteTasks: property.HasIncompleteTasks,
324			Title:              property.Title,
325		}
326	}
327	
328	func convertLocationFromStore(location *storepb.MemoPayload_Location) *v1pb.Location {
329		if location == nil {
330			return nil
331		}
332		return &v1pb.Location{
333			Placeholder: location.Placeholder,
334			Latitude:    location.Latitude,
335			Longitude:   location.Longitude,
336		}
337	}
338	
339	func convertLocationToStore(location *v1pb.Location) *storepb.MemoPayload_Location {
340		if location == nil {
341			return nil
342		}
343		return &storepb.MemoPayload_Location{
344			Placeholder: location.Placeholder,
345			Latitude:    location.Latitude,
346			Longitude:   location.Longitude,
347		}
348	}
349	
350	func convertVisibilityFromStore(visibility store.Visibility) v1pb.Visibility {
351		switch visibility {
352		case store.Private:
353			return v1pb.Visibility_PRIVATE
354		case store.Protected:
355			return v1pb.Visibility_PROTECTED
356		case store.Public:
357			return v1pb.Visibility_PUBLIC
358		default:
359			return v1pb.Visibility_VISIBILITY_UNSPECIFIED
360		}
361	}
362	
363	func convertVisibilityToStore(visibility v1pb.Visibility) store.Visibility {
364		switch visibility {
365		case v1pb.Visibility_PROTECTED:
366			return store.Protected
367		case v1pb.Visibility_PUBLIC:
368			return store.Public
369		default:
370			return store.Private
371		}
372	}
