22	export const parseFilterQuery = (query: string | null): MemoFilter[] => {
23	  if (!query) return [];
24	  try {
25	    return query.split(",").map((filterStr) => {
26	      const [factor, value] = filterStr.split(":");
27	      return {
28	        factor: factor as FilterFactor,
29	        value: decodeURIComponent(value || ""),
30	      };
31	    });
32	  } catch {
33	    return [];
34	  }
35	};
